//! NeXTSTEP 3.3 Platform Abstraction Layer
//!
//! This module provides the system-specific implementations for the standard library
//! on NeXTSTEP 3.3 (m68k).

#![allow(missing_docs, nonstandard_style)]

// =========================================================================
// THE ATOMIC HANDSHAKE
// Force the linkage of our hardware atomic polyfills to override the weak 
// software loops generated by `compiler_builtins`.
// =========================================================================
extern crate nextstep_atomics;
pub extern crate nextstep_sys;

pub mod alloc;
pub mod thread;
pub mod thread_local_dtor;
pub mod thread_local_key;

// Delegate to unsupported stubs for unimplemented modules
#[path = "../unsupported/args.rs"]    pub mod args;
#[path = "../unsupported/env.rs"]     pub mod env;
#[path = "../unsupported/fs.rs"]      pub mod fs;
#[path = "../unsupported/io.rs"]      pub mod io;
#[path = "../unsupported/net.rs"]     pub mod net;
#[path = "../unsupported/os.rs"]      pub mod os;
#[path = "../unsupported/process.rs"] pub mod process;
#[path = "../unsupported/time.rs"]    pub mod time;

// Where NeXTSTEP 3.3 perfectly matches standard POSIX, we can borrow 
// the existing Unix implementations to save time.
#[path = "../unix/path.rs"]
pub mod path;
#[path = "../unix/cmath.rs"]
pub mod cmath;

// NeXTSTEP has no pthreads. We must build custom primitives using 
// nextstep-atomics + Mach thread_switch.
pub mod condvar;
pub mod mutex;
pub mod rwlock;

// Stubs for unsupported features
#[path = "../unsupported/common.rs"]
#[deny(unsafe_op_in_unsafe_fn)]
mod common;
pub use common::*;
